/**
 * Governed-egress host rules, ported from the matcher Oya's egress proxy
 * (server/src/modules/control/egress.ts) and its managed browser
 * (browser/src/main/identity/host-rules.ts) share. A Rust copy cannot be byte-identical to that
 * TypeScript, so fixtures/egress/vectors.json, generated by running the TypeScript, is the
 * contract both sides pass: a host one side allows and the other blocks is a policy bypass.
 */
use crate::constants::MAX_HOST_UTF16;

/// Whether `host` matches any of `rules`, deciding exactly as Oya's proxy does.
///
/// A rule is an exact name, `*.domain` (any subdomain, never the bare domain) or a `*` inside a
/// label (`*-aiplatform.googleapis.com`). A wildcard never crosses a dot. The host is lowercased
/// and loses one trailing dot; one longer than 253 UTF-16 units matches nothing, as in JavaScript.
pub fn allowed_host(host: &str, rules: &[impl AsRef<str>]) -> bool {
    let lower = host.to_lowercase();
    let normalized = lower.strip_suffix('.').unwrap_or(&lower);
    normalized.encode_utf16().count() <= MAX_HOST_UTF16
        && rules
            .iter()
            .any(|rule| matches_rule(normalized, rule.as_ref()))
}

/// One rule against a normalized host: `*.` needs a non-empty prefix ending in a dot.
fn matches_rule(host: &str, rule: &str) -> bool {
    let host: Vec<char> = host.chars().collect();
    let Some(body) = rule.strip_prefix("*.") else {
        return glob(&rule.chars().collect::<Vec<_>>(), &host);
    };
    let body: Vec<char> = body.chars().collect();
    // TypeScript: `(?:[^.]*\.)+` is exactly "any string ending in a dot", so try every dot.
    (1..=host.len()).any(|split| host[split - 1] == '.' && glob(&body, &host[split..]))
}

/// A literal pattern whose `*` matches any run without a dot, anchored at both ends.
fn glob(pattern: &[char], text: &[char]) -> bool {
    // reachable[j]: the pattern consumed so far can end at text position j.
    let mut reachable = vec![false; text.len() + 1];
    reachable[0] = true;
    for &symbol in pattern {
        let mut next = vec![false; text.len() + 1];
        for j in 0..=text.len() {
            if !reachable[j] {
                continue;
            }
            if symbol == '*' {
                next[j] = true;
                let run = text[j..].iter().take_while(|c| **c != '.').count();
                next[j + 1..=j + run]
                    .iter_mut()
                    .for_each(|slot| *slot = true);
            } else if text.get(j) == Some(&symbol) {
                next[j + 1] = true;
            }
        }
        reachable = next;
    }
    reachable[text.len()]
}

#[cfg(test)]
mod tests {
    use super::allowed_host;

    #[test]
    fn subdomain_rule_excludes_the_bare_domain() {
        assert!(allowed_host("a.example.com", &["*.example.com"]));
        assert!(!allowed_host("example.com", &["*.example.com"]));
    }

    #[test]
    fn a_wildcard_never_crosses_a_label() {
        let vertex = ["*-aiplatform.googleapis.com"];
        assert!(allowed_host(
            "us-central1-aiplatform.googleapis.com",
            &vertex
        ));
        assert!(!allowed_host("a.b-aiplatform.googleapis.com", &vertex));
    }
}
